package com.pousadamarealta;

import com.pousadamarealta.domain.RatePlan;
import com.pousadamarealta.domain.ReservationStatus;
import com.pousadamarealta.infrastructure.Database;
import com.pousadamarealta.services.ReservationService;
import java.math.BigDecimal;
import java.time.LocalDate;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import static org.junit.jupiter.api.Assertions.*;

@Testcontainers
public class ReservationIntegrationTest {
  @Container
  static PostgreSQLContainer<?> postgres =
      new PostgreSQLContainer<>("postgres:18-alpine")
          .withDatabaseName("pousada")
          .withUsername("pousada")
          .withPassword("pousada123");

  @BeforeAll
  static void initializeDatabase() throws Exception {
    String jdbcUrl =
        String.format(
            "jdbc:postgresql://%s:%d/%s",
            postgres.getHost(), postgres.getFirstMappedPort(), postgres.getDatabaseName());
    Database.initialize(jdbcUrl, "pousada", "pousada123");
  }

  @Test
  public void testCreateAndConfirmReservation() throws Exception {
    LocalDate checkIn = LocalDate.of(2027, 3, 10);
    LocalDate checkOut = LocalDate.of(2027, 3, 12);

    var reservation =
        ReservationService.create(
            101, "João Silva", "joao@example.com", "12345678901", checkIn, checkOut, 2,
            RatePlan.STANDARD);

    assertEquals(101, reservation.roomNumber);
    assertEquals("João Silva", reservation.guestName);
    assertEquals(2, reservation.nights);
    assertEquals(ReservationStatus.PENDING, reservation.status);
    assertEquals(BigDecimal.ZERO, reservation.amountPaid);
  }

  @Test
  public void testConfirmReservation() throws Exception {
    LocalDate checkIn = LocalDate.of(2027, 3, 10);
    LocalDate checkOut = LocalDate.of(2027, 3, 12);

    var reservation =
        ReservationService.create(
            102, "Maria Silva", "maria@example.com", "98765432100", checkIn, checkOut, 2,
            RatePlan.STANDARD);

    var confirmed =
        ReservationService.confirm(reservation.id, new BigDecimal("499.80"));

    assertEquals(ReservationStatus.CONFIRMED, confirmed.status);
    assertEquals(new BigDecimal("499.80"), confirmed.amountPaid);
  }

  @Test
  public void testRoomUnavailableException() throws Exception {
    LocalDate checkIn = LocalDate.of(2027, 3, 10);
    LocalDate checkOut = LocalDate.of(2027, 3, 12);

    ReservationService.create(
        201, "João Silva", "joao@example.com", "12345678901", checkIn, checkOut, 2,
        RatePlan.STANDARD);

    assertThrows(
        Exception.class,
        () ->
            ReservationService.create(
                201,
                "Maria Silva",
                "maria@example.com",
                "98765432100",
                LocalDate.of(2027, 3, 11),
                LocalDate.of(2027, 3, 13),
                2,
                RatePlan.STANDARD));
  }

  @Test
  public void testCapacityExceededException() throws Exception {
    LocalDate checkIn = LocalDate.of(2027, 3, 10);
    LocalDate checkOut = LocalDate.of(2027, 3, 12);

    assertThrows(
        Exception.class,
        () ->
            ReservationService.create(
                101, "João Silva", "joao@example.com", "12345678901", checkIn, checkOut, 3,
                RatePlan.STANDARD));
  }
}

